fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Create a new vector to hold the result
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate over the indices of the input arrays
    for i in 0..a.len() {
        // Compute the bitwise OR and push it to the result vector
        result.push(a[i] | b[i]);
    }
    
    result
}